   444  krb5_error_code
   445  k5_pac_validate_client(krb5_context context,
   446                         const krb5_pac pac,
   447                         krb5_timestamp authtime,
   448                         krb5_const_principal principal,
   449                         krb5_boolean with_realm)
   450  {
   451      krb5_error_code ret;
   452      char *pac_princname, *princname;
   453      krb5_timestamp pac_authtime;
   454      int flags = 0;
   455
   456      ret = krb5_pac_get_client_info(context, pac, &pac_authtime,
   457                                     &pac_princname);
   458      if (ret != 0)
   459          return ret;
   460
   461      flags = KRB5_PRINCIPAL_UNPARSE_DISPLAY;
   462      if (!with_realm)
   463          flags |= KRB5_PRINCIPAL_UNPARSE_NO_REALM;
   464
   465      ret = krb5_unparse_name_flags(context, principal, flags, &princname);
   466      if (ret != 0) {
   467          free(pac_princname);
   468          return ret;
   469      }
   470
   471      if (pac_authtime != authtime || strcmp(pac_princname, princname) != 0)
   472          ret = KRB5KRB_AP_WRONG_PRINC;
   473
   474      free(pac_princname);
   475      krb5_free_unparsed_name(context, princname);
   476
   477      return ret;
   478  }
